from lecture_common import S,E,Q,L

def lessons():
 return [
 L(4,2,'시스템 보안의 이해와 인증','1. 시스템 보안의 이해 · 2. 계정 관리',[
 S([4,5],'시스템의 구성과 여섯 가지 관리 주제','시스템은 하드웨어와 그 위에서 동작하는 운영체제·응용프로그램을 포함합니다. 보안 대상은 PC만이 아니라 서버, 네트워크 장비, 데이터베이스와 서비스까지 이어집니다.','PPT의 여섯 주제는 계정 관리, 세션 관리, 접근 제어, 권한 관리, 로그 관리, 취약점 관리입니다. 계정은 사용 주체, 세션은 연결의 지속, 접근 제어는 연결 허용, 권한은 허용 작업, 로그는 활동 추적, 취약점 관리는 약점의 발견과 조치에 대응합니다.'),
 S(6,'식별과 인증, 네 가지 인증 수단','식별은 아이디처럼 자신이 누구인지 주장하는 과정이고 인증은 그 주장을 검증하는 과정입니다. 비밀번호가 맞는지 확인하는 것은 식별 문자열을 입력하는 일과 다릅니다.','알고 있는 것(비밀번호), 가지고 있는 것(토큰·인증 장치), 자신의 특징(지문 등 생체정보), 위치·접속 장소 같은 조건으로 인증 수단을 분류합니다. PPT의 콜백은 사전에 등록한 번호로 다시 연결해 확인하는 예입니다. 새로 제시한 임의 번호에 연락하는 것과 구분합니다.'),
 S([7,8],'OTP와 패스키의 차이','OTP는 매번 달라지거나 한 번 쓰는 코드를 확인하지만, 사용자가 가짜 사이트에 입력한 코드를 공격자가 즉시 전달하는 피싱에는 취약할 수 있습니다. 코드의 일회성과 피싱 저항성은 같은 성질이 아닙니다.','패스키는 WebAuthn/FIDO2의 공개키 방식으로 서비스와 연결된 인증을 수행합니다. 기기의 개인키를 서버에 보내지 않으며, 서비스 도메인과 연결된 검증으로 피싱 위험을 줄입니다.','계정 복구 과정, 이미 탈취된 세션, 기기 잠금과 이용 환경은 별도 관리가 필요합니다. 패스키의 장점과 모든 계정 위험이 사라진다는 주장은 구분합니다.')
 ],[Q('시스템 보안의 여섯 가지 관리 주제는?','계정·세션·접근 제어·권한·로그·취약점 관리다.','각 주제가 다루는 주체·연결·작업·기록·약점을 연결합니다.'),Q('식별과 인증은 어떻게 다른가?','식별은 신원의 주장, 인증은 그 주장의 검증이다.','아이디 제출만으로 신원 검증이 끝나지 않습니다.'),Q('OTP가 일회용이면 피싱 전달도 막는가?','아니다. 실시간 전달이 가능하며 패스키의 도메인 연결 검증과 다르다.','복구·세션·기기 관리도 함께 필요합니다.')]),
 L(5,2,'운영체제·DB·장비의 계정 관리','2. 계정 관리',[
 S([9,10],'Windows 사용자와 그룹 확인','Administrator는 대표적인 관리자 계정 이름입니다. 사용자 이름이 존재한다는 사실과 관리자 그룹 소속 여부는 따로 확인합니다. net users는 사용자 목록, net localgroup은 로컬 그룹 목록, net localgroup administrators는 관리자 그룹의 구성원을 확인하는 PPT 예입니다.','명령 결과를 읽을 때 계정 이름·활성 여부·그룹 소속을 구분합니다. 화면의 계정 수만으로 모든 사용자에게 같은 권한이 있다고 해석하면 안 됩니다.',code='net users\nnet localgroup\nnet localgroup administrators'),
 S(11,'Windows 기본 그룹의 역할','PPT의 기본 그룹 표는 관리자, 과거의 Power Users, 백업 담당자, 일반 사용자와 게스트를 비교합니다. 그룹 가입은 해당 그룹에 부여된 작업 권한에 영향을 줍니다.','아래 표는 PPT의 설명을 요약한 것이며 실제 로그인·원격 접근 권한은 Windows 버전과 로컬·도메인 정책을 함께 확인해야 합니다.',table=(['그룹','PPT에서 설명하는 역할'],[['Administrators','시스템·계정·자원 관리의 광범위한 관리자 권한'],['Power Users','과거 Windows의 제한된 관리 작업용 그룹'],['Backup Operators','백업 관련 권한과 로그인·종료 작업의 예'],['Users','일반 사용자 작업, 시스템 전체 변경 제한'],['Guests','임시·제한 사용자. PPT의 로컬/원격 로그인 비교는 당시 정책 예'] ])),
 S([12,13],'UNIX root와 /etc/passwd의 일곱 필드','root는 전통적으로 UID 0의 관리자 계정입니다. /etc/passwd는 사용자 정보를 콜론(:)으로 구분합니다. 비밀번호 칸의 x는 실제 비밀번호가 그 자리의 평문이라는 뜻이 아니라 별도 shadow 파일 등을 참조한다는 표기입니다.','순서는 사용자 이름, 비밀번호 자리, UID, 기본 GID, 설명, 홈 디렉터리, 로그인 셸입니다. UID는 사용자 식별 값이고 GID는 기본 그룹 식별 값이므로 서로 바꾸어 읽지 않습니다. 홈은 시작 디렉터리이고 셸은 로그인 후 실행 환경입니다.',code='사용자:x:UID:GID:설명:홈_디렉터리:로그인_셸'),
 S(14,'/etc/group과 기본·추가 그룹','/etc/group은 그룹 이름:비밀번호 자리:GID:구성원 목록 구조입니다. /etc/passwd의 GID와 맞춰 기본 그룹을 읽고, /etc/group의 구성원 목록으로 추가 그룹 관계를 확인합니다.','구성원 목록에 이름이 없다는 사실만으로 그 그룹과 관계가 없다고 판단하면 안 됩니다. 사용자의 기본 GID가 그 그룹을 가리킬 수 있기 때문입니다.',code='그룹:비밀번호_자리:GID:추가_구성원1,추가_구성원2'),
 S(15,'데이터베이스와 네트워크 장비의 계정','PPT는 SQL Server의 sa, Oracle의 sys·system 같은 대표 관리 계정을 소개합니다. 이름만으로 모든 버전의 생성·관리 권한을 확정하지 말고 실제 부여된 역할을 확인합니다. 특히 system의 데이터베이스 생성 가능 여부는 권한·구성에 따라 판단합니다.','TFTP는 프로토콜 자체에 일반적인 사용자 인증 기능이 없는 전송 방식의 예입니다. Cisco 장비의 사용자 모드와 특권 모드는 허용 명령의 수준을 구분하며, TACACS+는 중앙에서 계정 인증과 명령 권한을 관리하는 예입니다. 장비 로그인에 성공했다고 모든 설정 명령이 허용되는 것은 아닙니다.')
 ],[Q('/etc/passwd의 UID와 GID는 각각 무엇인가?','사용자 식별 값과 기본 그룹 식별 값이다.','일곱 필드의 순서와 /etc/group의 GID를 함께 읽습니다.'),Q('net users와 net localgroup administrators는 무엇을 비교하나?','사용자 목록과 관리자 그룹 구성원을 비교한다.','계정 존재와 관리자 권한 소속은 다른 정보입니다.'),Q('장비의 사용자 모드·특권 모드를 나누는 목적은?','사용자에게 허용할 관리 명령의 수준을 구분하기 위해서다.','인증 결과와 명령별 인가를 연결합니다.')],[E('버전과 정책에 따라 달라지는 계정 설명','PPT의 Guests·Power Users 표는 과거 Windows의 설명입니다. 현대 Windows의 실제 로컬·원격 로그인 허용은 정책과 구성에 따라 달라집니다. /etc/passwd의 로그인 셸도 모든 시스템에서 bash로 고정되는 것은 아닙니다.',links=[('passwd 파일 형식','https://man7.org/linux/man-pages/man5/passwd.5.html')])]),
 L(6,2,'세션 관리','3. 세션 관리',[
 S([16,17],'세션의 의미와 지속적인 확인','세션은 통신이나 로그인 이후 일정 기간 유지되는 연결·상태입니다. PPT는 친구와 통화를 이어 가는 상황, 「해님 달님」에서 손을 확인하는 이야기를 통해 처음 확인한 상대가 계속 같은 상대인지 묻습니다.','세션 중 자리를 비우거나 연결이 방치되면 다른 사람이 기존 권한을 이용할 수 있습니다. Windows 화면 잠금·화면 보호기와 원격 UNIX 연결의 유휴 종료는 사용 환경에 맞춘 관리 예입니다. 화면 잠금과 네트워크 세션 종료는 같은 동작이 아닙니다.'),
 S([18,19],'세션 수명·재발급·쿠키 속성','로그인하거나 권한이 바뀔 때 세션 식별자를 새로 발급하면 이전 식별자의 재사용 위험을 줄일 수 있습니다. 로그아웃은 화면 전환만이 아니라 서버에서 해당 세션을 더 이상 유효하게 인정하지 않는 처리가 필요합니다.','유휴 만료는 마지막 활동 이후의 시간, 절대 만료는 활동 여부와 무관한 전체 세션 수명을 제한합니다. Secure는 HTTPS 전송, HttpOnly는 스크립트의 쿠키 접근 제한, SameSite는 교차 사이트 요청에서의 쿠키 전송 정책과 관련됩니다. 속성은 목적이 서로 다르므로 하나로 모든 세션 공격을 막는다고 답하지 않습니다.')
 ],[Q('화면 잠금과 서버 세션 만료는 같은가?','아니다. 기기의 대화형 접근 제한과 서버 인증 상태의 수명 관리다.','통신·로그인 상태가 어느 곳에 남는지 구분합니다.'),Q('유휴 만료와 절대 만료의 차이는?','마지막 활동 이후 시간과 최초 생성 이후 전체 시간을 각각 제한한다.','계속 요청을 보내도 절대 만료에 도달할 수 있습니다.'),Q('HttpOnly와 Secure의 역할은?','스크립트의 쿠키 접근 제한과 HTTPS 전송 제한이다.','쿠키 속성과 서버 측 무효화는 별개입니다.')]),
 L(7,2,'시스템 접근 제어','4. 접근 제어',[
 S(20,'접근 제어와 관리 인터페이스','접근 제어는 사용자·장치·네트워크가 자원에 연결할 수 있는 조건을 결정합니다. IP 주소와 포트는 관리 서비스의 노출과 정책을 읽는 기본 요소입니다.','PPT의 대표 포트 표는 서비스 식별의 출발점입니다. 실제 포트는 변경될 수 있으며 같은 번호가 보인다는 사실만으로 안전성이나 사용 주체까지 확정하지 않습니다.',table=(['인터페이스','PPT의 포트/특징'],[['Telnet','23 · 평문 관리 접속'],['SSH/SFTP','22 · 암호화된 원격 접속/파일 전송'],['XDMCP','PPT에는 6000으로 표기 · 아래 정정 참조'],['FTP','제어 연결 21'],['Windows 원격 터미널','3389'],['VNC/Radmin','제품·설정별 원격 관리 포트'] ])),
 S(21,'관리 접속의 노출 줄이기','사용하지 않는 관리 서비스는 비활성화하고 평문 원격 접속을 줄입니다. 관리 인터페이스가 누구에게 노출돼 있고 어떤 계정·장치·네트워크만 접속 가능한지 확인합니다.','접속을 허용한 뒤에도 권한과 로그를 관리해야 합니다. IP 제한 하나와 사용자 인증은 다른 통제이므로 함께 확인합니다.'),
 S(22,'UNIX의 inetd와 TCP Wrapper','PPT의 전통적 구성은 inetd가 요청을 받아 tcpd(TCP Wrapper)를 거치고, 허용·거부 조건을 확인한 뒤 서비스로 연결하는 흐름입니다. tcpd를 사용하는 서비스와 정책 파일의 적용 범위를 함께 읽습니다.','접근을 거절한 기록과 허용한 기록은 정책 확인에 쓰입니다. 이 구조는 역사적 서비스 관리 예이며 모든 현대 서비스가 inetd와 TCP Wrapper를 거치는 것은 아닙니다.'),
 S(23,'데이터베이스의 IP·계정 접근 제어','Oracle의 PPT 예는 $ORACLE_HOME/network/admin/sqlnet.ora에서 접속 노드를 제어합니다. tcp.invited_nodes는 200.200.200.100·200.200.200.200을 허용 목록으로, tcp.excluded_nodes는 200.200.200.150을 제외 목록으로 나타냅니다. 실제 적용에는 버전별 노드 검사 활성화와 설정 위치를 확인해야 합니다.','MySQL 예의 사용자@호스트는 계정 이름과 접속 출처를 함께 지정한다는 뜻입니다. DB/테이블과 GRANT 권한의 범위도 따로 읽습니다. PPT의 GRANT … IDENTIFIED BY 문법은 과거 버전 예이며 새 버전의 계정 생성·권한 부여 절차와 구분합니다.',code='tcp.invited_nodes=(200.200.200.100,200.200.200.200)\ntcp.excluded_nodes=(200.200.200.150)\nMySQL: 사용자@호스트 + 대상 DB/테이블 + 부여 권한'),
 S(24,'응용프로그램과 장비의 접근 제어','NGINX는 allow·deny 규칙을 설정한 순서대로 확인하고 처음 일치한 규칙을 적용합니다. 허용하려는 대상을 먼저 적고 나머지를 거절하는 구성에서 순서를 바꾸면 결과가 달라집니다.','장비 자체의 관리 인터페이스 접속 제한과, 장비를 통과하는 데이터 트래픽의 ACL은 서로 다른 대상입니다. 전자는 관리 권한 노출, 후자는 전달할 패킷의 조건을 통제합니다.'),
 S([25,26],'제로 트러스트의 판단 요소','내부망이라는 위치만으로 무조건 신뢰하지 않고 사용자 신원, 장치 상태, 요청 자원, 위험, 시간과 상황을 함께 평가합니다. 인증된 계정도 필요한 자원에 필요한 범위만 접근하도록 결정합니다.','접근 결정을 내린 근거와 결과를 기록하고 상태 변화에 따라 다시 평가합니다. 제로 트러스트는 특정 제품 하나나 모든 접속을 무조건 거절하는 규칙의 이름이 아닙니다.')
 ],[Q('관리 인터페이스 ACL과 통과 트래픽 ACL의 차이는?','장비에 접속하는 관리 요청과 장비가 전달하는 데이터 요청을 각각 통제한다.','정책이 보호하는 대상이 다릅니다.'),Q('NGINX allow·deny 규칙의 판단 기준은?','순서대로 확인해 처음 일치한 규칙을 적용한다.','특정 IP 허용과 전체 거절의 순서가 중요합니다.'),Q('제로 트러스트에서 내부망 위치만으로 접근을 허용하나?','아니다. 신원·장치·자원·위험·상황을 함께 평가한다.','내부/외부 구분과 사용자별 최소 권한은 다릅니다.')],[E('XDMCP 포트 및 규칙의 정정','XDMCP는 UDP 177을 사용합니다. PPT의 6000은 X11 디스플레이 연결에서 사용하는 TCP 6000 계열과 구분해야 합니다. NGINX의 순서 규칙은 NGINX 접근 모듈의 동작이며 다른 제품의 정책 처리 방식까지 일반화하지 않습니다.',links=[('XDMCP 규격','https://xorg.freedesktop.org/archive/X11R7.7/doc/libXdmcp/xdmcp.html'),('NGINX access 모듈','https://nginx.org/en/docs/http/ngx_http_access_module.html')])]),
 L(8,2,'운영체제의 파일 권한','5. 권한 관리 · 운영체제',[
 S(27,'Windows NTFS의 권한','PPT의 여섯 권한은 모든 권한, 수정, 읽기 및 실행, 폴더 내용 보기, 읽기, 쓰기입니다. 폴더/파일의 보안 속성에서 사용자·그룹과 권한 항목을 연결합니다. 읽기와 실행, 쓰기와 삭제·수정을 같은 권한으로 취급하지 않습니다. 파일에 직접 준 권한과 폴더에서 상속된 권한도 구분합니다.','사용자가 여러 그룹에 속하면 여러 허용·거부 항목이 평가됩니다. PPT의 세 요약 규칙은 권한 누적, 파일 권한과 상위 디렉터리 권한의 구분, 거부 우선입니다. 실제 결과는 명시적·상속된 ACE의 순서와 적용 대상을 확인해야 합니다.',table=(['권한','PPT 설명의 핵심과 읽는 기준'],[['모든 권한','읽기·쓰기·실행·삭제 및 권한/소유권 변경 같은 광범위한 작업'],['수정','읽기·실행·쓰기·삭제를 포함하는 작업 수준'],['읽기 및 실행','내용을 읽고 프로그램을 실행·디렉터리를 탐색하는 작업'],['폴더 내용 보기','디렉터리의 파일·하위 디렉터리 이름 확인'],['읽기','내용·속성 등 읽기 작업'],['쓰기','파일·하위 디렉터리 생성 및 내용 기록 등 쓰기 작업'] ])),
 S(28,'UNIX의 파일 종류와 rwx','ls -al의 첫 문자는 일반 파일(-), 디렉터리(d), 심볼릭 링크(l) 등의 유형입니다. 뒤의 아홉 문자를 소유자·그룹·기타 사용자 세 묶음으로 나누어 r(읽기), w(쓰기), x(실행)를 읽습니다.','각 묶음의 4·2·1 가중치를 더하면 숫자 권한으로 표현할 수 있습니다. 파일과 디렉터리에서 읽기·쓰기·실행의 의미가 다르므로 파일 내용 열람과 디렉터리 탐색을 구분합니다. 소유자·그룹 이름과 현재 요청자의 소속을 먼저 확인한 뒤 해당 묶음을 적용합니다.')
 ],[Q('rwx의 가중치는?','읽기 4, 쓰기 2, 실행 1이다.','묶음별로 합산하며 세 자리를 한꺼번에 더하지 않습니다.'),Q('ls -al의 첫 문자 d와 뒤의 rwx는 무엇이 다른가?','d는 파일 유형, rwx는 작업 권한이다.','유형과 세 사용자 범주의 권한을 나눠 읽습니다.'),Q('NTFS에서 그룹 허용만 보고 최종 권한을 확정할 수 있나?','아니다. 거부·상속·명시적 항목과 실제 평가 순서를 확인한다.','PPT의 누적/거부 우선 요약만으로 모든 ACL을 설명할 수 없습니다.')],[E('NTFS의 거부 우선 설명을 읽는 범위','Windows의 권장 ACE 순서는 명시적 항목을 상속 항목보다 앞에 두고, 같은 명시적 항목 안에서 거부를 허용보다 앞에 둡니다. 따라서 모든 상속 거부가 모든 명시적 허용보다 우선한다고 외우면 틀릴 수 있습니다.','PPT의 읽기 및 실행 항목에 적힌 「파일 옮기기」는 해당 권한만으로 모든 이동이 가능하다는 뜻으로 사용하면 안 됩니다. 이동에는 원본·목적지의 쓰기·삭제 등 권한이 추가로 관계합니다. 또한 NT 4.0 이후의 모든 설치가 반드시 NTFS라는 식으로 일반화하지 않습니다.',links=[('Microsoft ACE 순서','https://learn.microsoft.com/en-us/windows/win32/secauthz/order-of-aces-in-a-dacl')])]),
 L(9,2,'데이터베이스와 응용프로그램의 권한','5. 권한 관리 · DB와 응용프로그램',[
 S(29,'DDL·DML·DCL','DDL은 CREATE·DROP·ALTER처럼 구조를 정의·변경하는 명령, DML은 SELECT·INSERT·UPDATE·DELETE처럼 데이터를 조회·조작하는 명령입니다. DCL의 GRANT·DENY·REVOKE는 권한의 부여·거부·회수에 대응합니다. DENY 등 구체적 지원 문법은 제품별로 확인합니다.','PPT는 이 세 분류를 통해 데이터 조회 권한과 테이블 구조 변경 권한, 권한을 부여하는 권한을 구분합니다. DDL이 최초 설치 때만 사용된다는 뜻은 아닙니다. 운영 중에도 구조 변경 권한은 통제해야 합니다.'),
 S(30,'뷰를 통한 공개 범위 제한','뷰(View)는 원본 테이블에서 필요한 행·열을 선택해 사용자에게 보이는 구조를 만들 수 있습니다. 이름·학과만 공개할 뷰를 만들고 그 뷰에 대한 조회 권한을 주는 식으로 개인정보 노출 범위를 줄입니다.','뷰 권한을 제한해도 사용자가 원본 테이블을 직접 조회할 수 있으면 제한을 우회할 수 있습니다. 뷰 정의, 뷰 권한, 원본 접근 권한을 함께 확인합니다.'),
 S([31,32],'응용프로그램의 실행 권한과 JIT','응용프로그램은 실행 계정의 권한으로 파일·DB·운영체제 기능을 사용합니다. IIS의 제한된 실행 계정과 UNIX의 nobody는 서비스가 관리자 권한 전체를 갖지 않게 하는 예입니다. 프로그램에 취약점이 있어도 피해 범위를 줄이려면 필요한 권한만 부여해야 합니다.','JIT(Just-In-Time) 권한은 승인된 작업에 한해 필요한 시간 동안 권한을 올리고 종료 후 회수합니다. 서비스 계정·자동화 비밀정보도 소유자, 사용 목적, 보관과 만료·회수 여부를 관리해야 합니다.')
 ],[Q('CREATE·SELECT·GRANT는 각각 어떤 분류인가?','DDL·DML·DCL이다.','구조 정의·데이터 조작·권한 제어의 목적을 연결합니다.'),Q('공개 뷰를 만들면 원본 테이블 권한을 확인하지 않아도 되나?','아니다. 원본 직접 조회 권한이 남아 있으면 공개 범위를 우회할 수 있다.','제공 인터페이스와 실제 데이터 권한을 함께 봅니다.'),Q('서비스 계정 최소 권한과 JIT의 목적은?','항상 유지하는 권한과 일시적으로 필요한 권한의 범위를 줄이는 것이다.','작업 종료 후 회수와 기록까지 포함합니다.')]),
 L(10,2,'로그 관리','6. 로그 관리',[
 S(33,'AAA와 감사 기록','AAA의 Authentication은 인증, Authorization은 인가, Accounting은 활동의 기록·추적입니다. 누가 어떤 자원을 언제 어떻게 사용했는지 확인하는 일이 마지막 A에 해당합니다.','로그는 사건을 재구성하는 근거입니다. 기록을 켰는지뿐 아니라 필요한 이벤트가 남고, 시간·주체·결과가 해석 가능하며, 삭제·변조를 막고 보존하는지도 확인합니다.'),
 S([34,35,36],'Windows 감사 정책과 이벤트 뷰어','감사 정책에서 로그인, 계정 변경, 권한 사용, 프로세스 생성 등의 성공·실패 이벤트를 선택합니다. 정책을 적용한 뒤 이벤트 뷰어에서 시각·원본·이벤트 ID·사용자·컴퓨터·상세 내용을 확인합니다. 설정 화면만으로 실제 수집 성공을 단정하지 않습니다.','PPT의 아홉 감사 항목은 아래와 같습니다. 계정 로그온은 계정 자격의 검증과, 로그온 이벤트는 해당 컴퓨터의 세션 생성·종료와 관련되므로 도메인 환경에서는 수집 위치도 달라질 수 있습니다.',table=(['감사 항목','주요 관찰 대상'],[['개체 액세스','파일 등 감사 대상 객체에 대한 접근'],['계정 관리','계정 생성·변경·삭제'],['계정 로그온','계정 자격 검증'],['권한 사용','민감한 권한의 사용'],['로그온 이벤트','컴퓨터의 로그인·로그아웃'],['디렉터리 서비스 액세스','디렉터리 객체 접근'],['정책 변경','감사·보안 정책 변경'],['프로세스 추적','프로세스 생성·종료 등'],['시스템 이벤트','시작·종료·시스템 보안 관련 사건'] ])),
 S([37,38],'UNIX 로그 위치와 로그인 기록','PPT는 /usr/adm, /var/adm, /var/log, /var/run 같은 역사적 경로를 소개합니다. 배포판과 서비스에 따라 실제 저장 위치·저장 형식이 다르며 /var/run의 런타임 상태와 영구 로그를 구분합니다.','utmp는 현재 로그인 상태의 바이너리 자료이며 w·who·users 등 도구로 읽습니다. PPT의 whodo·finger도 사용자·접속 정보 확인 예입니다. wtmp는 로그인·로그아웃·재부팅 이력을 기록하며 last로 확인하는 대표 예입니다. 단순 텍스트 파일처럼 편집해 해석하지 않습니다.'),
 S([39,40],'su·셸 이력·syslog','secure 또는 sulog는 인증·su 전환 등 관련 기록을 확인하는 예이며 PPT에는 /var/adm/sulog가 등장합니다. 사용자 전환 전후의 주체와 성공·실패를 함께 읽습니다.','셸 history는 실행 명령을 파악하는 보조 자료지만 기록 누락·변경 가능성이 있습니다. syslog와 /var/log/messages는 다양한 시스템 메시지를 모으는 전통적 구성입니다. 한 파일에 모든 활동이 완전하게 남는다고 가정하지 않습니다.'),
 S(41,'SQL Server Audit와 과거 C2 감사','SQL Server Audit는 서버 또는 데이터베이스 단위로 감사할 작업을 선택하고 감사 파일이나 Windows 이벤트 로그에 결과를 기록합니다. 감사 범위와 출력 대상을 따로 지정한다는 점이 핵심입니다.','C2 감사 모드는 과거 방식이며 PPT는 향후 제거 예정인 예로 표시합니다. 새 구성에서는 필요한 이벤트를 SQL Server Audit로 선택하는 흐름으로 이해합니다.'),
 S([42,43],'MySQL의 다섯 가지 로그','각 로그의 목적을 구분해야 장애 분석·쿼리 추적·성능 분석·복제/복구 자료를 혼동하지 않습니다. Binary 로그와 Relay 로그를 모든 수신 조회문의 감사 로그라고 해석하지 않습니다.',table=(['종류','기록 목적'],[['Error','시작·종료와 서버 오류·진단 메시지'],['General','클라이언트가 보낸 연결·쿼리 등 일반 실행 요청'],['Slow Query','설정된 조건에 맞는 느린 쿼리와 실행 정보'],['Binary','데이터 변경 이벤트 등 복제·복구에 쓰는 이력'],['Relay','복제 서버가 받아 이후 적용할 이벤트'] ])),
 S(44,'MySQL General Log 설정 읽기','show variables like \'general%\'는 general_log의 ON/OFF와 파일 경로 같은 현재 값을 확인하는 예입니다. set global general_log = ON/OFF는 전역 일반 로그를 켜거나 끄는 PPT의 명령입니다.','수신 쿼리에는 민감한 값이 들어갈 수 있고 많은 기록이 생성됩니다. 학습에서는 설정 확인·출력 대상·보존 범위를 함께 읽으며 이 웹사이트에서 실제 DB 설정을 변경하지 않습니다.',code="show variables like 'general%';\nset global general_log = ON;\nset global general_log = OFF;"),
 S([45,46],'Oracle 통합 감사와 감사 결과','Oracle Unified Auditing은 정책을 통해 로그인, 권한 사용, 객체 작업 등 필요한 이벤트를 선택합니다. UNIFIED_AUDIT_TRAIL에서 감사 결과를 조회하고 관리자 작업과 실패한 접근을 구분해 탐지에 연결합니다.','기존 AUDIT_TRAIL은 전통적 감사 방식의 설정입니다. PPT는 과거의 문장·권한·객체 감사와 새 통합 감사의 개념을 비교하면서 제품 버전과 지원 상태를 확인하도록 설명합니다. 감사 결과의 열람 권한·보존 기간·변조와 삭제 감시도 관리 대상입니다.'),
 S(47,'DB 트래픽을 통한 감사','패시브 DB 모니터링은 통신 경로를 복제·탭으로 관찰해 쿼리와 활동을 분석하는 방식입니다. DB 자체 감사와 네트워크 관찰은 수집 지점이 다릅니다.','PPT의 「모든 쿼리」「성능 영향 없음」 같은 표현은 관찰 가능한 경로와 구성의 조건 안에서 읽어야 합니다. 암호화·우회 경로·로컬 접속은 가시성에 영향을 주므로 빠짐없는 기록을 보장한다고 단정하지 않습니다.'),
 S([48,49],'IIS 로그 형식과 샘플 해석','IIS는 W3C 확장 형식, NCSA, IIS 형식과 사용자 정의 방식 등을 사용합니다. 같은 숫자 위치라도 로그 형식과 필드 선택이 다르면 뜻이 달라집니다. W3C의 #Fields 선언을 먼저 확인합니다.','PPT 예의 날짜 2012-06-03, 서버 IP 192.168.137.128, GET 요청 경로, 포트 80, 클라이언트 주소, 브라우저 정보, 상태 200과 처리 시간 225를 필드명에 맞춥니다. 200 뒤의 0·0을 무조건 송수신 바이트라고 읽으면 안 됩니다. sc-substatus·sc-win32-status일 수 있으며 time-taken은 밀리초로 읽습니다.'),
 S(50,'Apache access_log와 LogFormat','Apache는 httpd.conf 등의 LogFormat에서 로그 필드 순서를 정의하고 access_log에 요청 결과를 기록합니다. combined 같은 형식 이름만 외우기보다 실제 형식 문자열과 한 줄의 값을 대응시키는 것이 중요합니다.','주소·시각·요청줄·상태·전송량·참조 페이지·User-Agent를 구분합니다. 비어 있는 값의 - 표시는 값이 없다는 뜻일 수 있으며 숫자 0과 무조건 같지 않습니다.'),
 S(51,'Apache 필드 표 읽기','PPT 표의 각 지시자는 아래 목적에 대응합니다. %{Header}e는 환경변수, %{User-Agent}i는 요청 헤더 값처럼 중괄호의 이름과 뒤 문자가 함께 의미를 정합니다. PPT의 과거 %c 연결 상태 표기는 사용하는 Apache 버전의 지원 여부를 확인할 항목입니다.',table=(['지시자','뜻'],[['%a / %A','클라이언트 IP / 서버 로컬 IP'],['%b','응답 본문 바이트, 없는 경우 -'],['%c','PPT의 과거 연결 종료 상태 표기'],['%{이름}e','이름으로 지정한 환경변수'],['%f','요청에 대응한 파일 이름'],['%h / %H','원격 호스트 / 요청 프로토콜'],['%l','ident 정보'],['%m / %p / %P','메서드 / 서버 포트 / 처리 프로세스 ID'],['%q / %r','쿼리 문자열 / 요청 첫 줄'],['%s','응답 상태 코드'],['%{형식}t / %T','요청 시각 / 처리 시간(초)'],['%u / %U','인증 사용자 / 쿼리 제외 URL 경로'],['%v / %V','서버 이름 관련 값(설정에 따라 구분)'] ])),
 S(52,'Apache 샘플의 상태·바이트·사용자','PPT의 2017-06-06 +0900 로그에서 403은 접근 금지 응답, 4609는 해당 형식의 바이트 필드입니다. 사용자·ident 자리에 -가 있으면 그 값이 제공되지 않은 것으로 읽습니다.','403 한 줄은 그 요청이 거절된 결과를 보여 줄 뿐, 모든 공격이 차단되거나 서버가 안전하다는 증거는 아닙니다. 요청 헤더를 나타내는 %i는 실제로 %{User-Agent}i처럼 헤더 이름과 함께 해석해야 합니다.'),
 S([53,54],'보안 장비·관리 시스템과 원격 로그','방화벽·IDS·IPS는 허용·차단·탐지 등 서로 다른 관찰 결과를 남깁니다. SIEM은 여러 출처의 이벤트를 모아 분석하고, NMS·MRTG는 상태·트래픽 변화, TACACS+는 관리 계정·명령 활동의 근거를 제공할 수 있습니다.','원격 로그 서버는 침해된 장치의 로컬 기록만 믿는 위험을 줄입니다. 전송·수집 권한·저장 보호·보존과 시간 동기화를 함께 구성해야 하며, 원격 저장만으로 모든 변조 가능성이 사라지지는 않습니다.'),
 S([55,56],'상관 분석과 사건의 재구성','PPT의 실패 로그인 반복, 성공 로그인, 관리자 권한 사용, 설정 변경을 한 흐름으로 연결할 때 계정·장치·대상·시간이 같은지 확인합니다. 서로 무관한 이벤트를 단순히 인접한 줄이라는 이유로 한 공격으로 묶으면 안 됩니다.','실패 후 성공과 권한 변경은 조사할 신호지만 그 자체로 공격을 확정하지 않습니다. 정상 관리 작업 여부와 추가 로그를 대조하고, 로그가 없는 구간과 수집 지점의 한계를 표시합니다.')
 ],[Q('AAA의 마지막 A와 로그 관리의 목적은?','Accounting, 즉 활동을 기록하고 추적하는 것이다.','인증·인가·활동 기록을 구분합니다.'),Q('General·Slow Query·Binary·Relay 로그는 같은가?','아니다. 수신 요청·느린 실행·변경 이력·복제 수신 이벤트라는 목적이 다르다.','장애 기록은 Error 로그와 구분합니다.'),Q('IIS·Apache 로그 한 줄을 해석하기 전에 확인할 것은?','#Fields 또는 LogFormat과 시간·단위·수집 위치다.','고정된 칸 번호만 외우면 상태·크기·시간을 혼동합니다.')],[E('출처 오류와 로그 해석 보충','PPT의 /usr/adm 설명에 포함된 데이터베이스 오브젝트 언급은 로그 경로 설명과 맞지 않는 문장입니다. 경로는 UNIX 배포판·서비스별 실제 설정을 기준으로 확인합니다. IIS의 200 0 0은 선택한 필드가 상태/하위 상태/Win32 상태일 수 있으므로 파일 헤더를 기준으로 판독합니다.',links=[('IIS 로그 필드','https://learn.microsoft.com/en-us/iis/configuration/system.applicationhost/sites/site/logfile/'),('Apache LogFormat','https://httpd.apache.org/docs/2.4/mod/mod_log_config.html')])]),
 L(11,2,'취약점 관리와 모바일 보안','7. 취약점 관리 · 8. 모바일 보안',[
 S([57,58,59],'취약점의 우선순위와 조치 절차','자산·제품 버전·지원 종료 여부와 외부 노출, 실제 악용 여부, 업무 중요도를 함께 확인해 조치 순서를 정합니다. KEV처럼 실제 악용이 알려진 항목은 단순한 점수와 다른 판단 근거가 됩니다.','패치는 영향 확인, 시험, 롤백 준비, 배포, 적용 검증으로 이어집니다. 즉시 수정할 수 없는 경우 접근 제한·기능 비활성화·노출 감소 같은 임시 조치와 책임자·기한을 정하고 예외를 계속 방치하지 않습니다.'),
 S(60,'불필요한 고위험 기능: xp_cmdshell','SQL Server의 xp_cmdshell은 DB 문맥에서 운영체제 명령 실행으로 이어질 수 있는 기능의 예입니다. 애플리케이션에 필요한지, 누가 실행할 수 있는지, 서비스 계정 권한이 무엇인지 확인합니다.','DB 관리자 기능과 일반 업무 계정의 권한을 나누고 불필요한 기능은 사용하지 않는 방향으로 관리합니다. 본문은 기능의 위험과 통제에 관한 설명이며 실제 명령 실행 실습은 하지 않습니다.'),
 S(61,'SMTP의 정보 노출: VRFY·EXPN','sendmail 등 SMTP 서비스에서 VRFY는 사용자 확인, EXPN은 메일링 목록 확장과 관련된 명령의 예입니다. 응답을 통해 계정이나 그룹 정보를 추측할 수 있어 불필요한 노출을 줄여야 합니다.','서비스 배너·진단·편의 기능도 공격자가 수집하는 정보가 될 수 있습니다. 기능 필요성과 공개 범위를 확인하고 버전·설정에 맞게 제한합니다.'),
 S([62,63],'모바일 운영체제의 역사','PPT는 Palm과 Windows CE(1996), BlackBerry, iPhone/iOS(2007), Android와 HTC Dream의 등장 순서로 모바일 환경을 소개합니다. 단말의 이동성과 통신·앱 기능이 확대되면서 보안 대상도 늘어났습니다.','아이폰 SDK 공개(2008년 3월 6일), iPhone OS에서 iOS로의 명칭 변경(2010), Android의 디저트 코드명은 플랫폼 발전의 배경입니다. PPT의 Android 1.0·HTC Dream 2007년 표기와 1.1 코드명 설명은 아래 정정과 구분합니다.'),
 S([64,65,66,67],'iOS의 보안 구조','보안 부팅과 코드 서명은 실행되는 소프트웨어의 신뢰를 확인하고, 앱 샌드박스는 앱이 다른 앱·시스템의 자원에 자유롭게 접근하지 못하도록 경계를 만듭니다. Data Protection과 Keychain은 데이터·비밀정보 보관에 관련됩니다.','백그라운드 동작은 운영체제가 관리하는 제한된 기능으로 이해하며 모든 백그라운드 실행이 금지된다는 뜻은 아닙니다. 일반 앱이 원격 연결만으로 임의의 OS 명령을 실행할 권한을 얻는 것도 아닙니다.','탈옥은 기본 보호를 약화할 수 있지만 위험이 탈옥에만 한정되지는 않습니다. 업데이트, 피싱·악성 앱 주의, 분실 시 잠금과 복구, 앱 권한 관리가 함께 필요합니다.'),
 S([68,69],'Android의 보안 구조','Android는 Linux 기반의 앱별 UID와 샌드박스, SELinux 정책으로 접근 경계를 관리합니다. Verified Boot와 앱 서명은 부팅·설치·업데이트 과정의 신뢰와 연결됩니다.','런타임 권한은 앱이 위치·카메라·마이크 등 민감한 기능을 사용할 조건을 제어합니다. OS 버전과 보안 패치, 제조사·기기의 업데이트 지원, 설치 출처를 함께 확인해야 합니다. Android라는 이름만으로 보호 수준을 확정하지 않습니다.'),
 S(70,'iOS와 Android의 비교 기준','두 플랫폼 모두 앱 격리, 서명 검증, 부팅 보호, 키·데이터 보호 기능을 갖지만 배포·업데이트 체계와 구체적인 정책은 다릅니다. PPT의 비교는 기능별 구조를 설명하는 것이며 한쪽이 모든 상황에서 안전하다는 순위를 뜻하지 않습니다.','샌드박스는 앱 사이의 경계, 코드 서명은 소프트웨어 출처·변경 검증, 안전한 키 저장은 비밀정보 노출 감소, 업데이트는 알려진 취약점 수정이라는 목적에 대응시킵니다.'),
 S(71,'모바일 앱의 권한·저장·통신 점검','위치·카메라·마이크 권한은 업무에 필요한 때와 범위만 허용합니다. 비밀정보는 플랫폼의 안전한 저장 기능을 사용하고 앱에 평문으로 고정하지 않는 방향으로 관리합니다.','앱의 출처와 서명, 업데이트, 네트워크 통신 보호와 WebView의 입력·콘텐츠 경계를 확인합니다. 설치 성공과 안전한 동작은 같은 판단이 아닙니다.'),
 S(72,'Bluetooth·Wi-Fi와 주변 탐색','필요한 무선 기능만 사용하고 페어링된 장치·공개 상태·앱 권한을 확인합니다. PPT의 워드라이빙은 무선 AP를 이동하며 찾는 활동, 블루프린팅은 Bluetooth 장치의 정보를 식별하는 역사적 탐색 예입니다.','장치가 검색된다는 사실과 실제 데이터 침해가 성공했다는 사실은 다릅니다. 검색 결과만으로 접근 권한이나 데이터 유출을 단정하지 않습니다.'),
 S(73,'블루스나프·블루버그와 방어','블루스나프는 Bluetooth를 통한 무단 정보 접근, 블루버그는 취약한 연결·명령 기능의 악용으로 장치 기능을 조작하는 역사적 사례입니다. 명칭과 피해 형태를 구분합니다.','운영체제·장치 업데이트, 불필요한 검색 가능 상태와 연결 해제, 모르는 페어링 거절, 기존 페어링과 앱 Bluetooth 권한 검토를 연결합니다. 과거 취약 사례가 모든 최신 장치에서 같은 조건으로 재현되는 것은 아닙니다.')
 ],[Q('취약점 수정 순서는 점수 하나만으로 정하나?','아니다. 실제 악용·노출·자산 중요도·버전과 지원 상태를 함께 본다.','패치 적용 후 검증과 예외 기한도 필요합니다.'),Q('iOS·Android의 샌드박스와 코드 서명은 무엇을 보호하나?','앱의 접근 경계와 실행 소프트웨어의 신뢰를 각각 보호한다.','데이터 저장·권한·업데이트도 별도 통제입니다.'),Q('블루스나프와 블루버그의 핵심 차이는?','무단 정보 접근과 장치 기능·명령 악용이라는 피해 형태의 차이다.','검색 가능 상태만으로 두 공격이 성공했다고 보지 않습니다.')],[E('Android 연표의 정정','Android 공식 개발자 블로그의 1.0 SDK 및 첫 G1 발표 기록은 2008년 9월 23일입니다. 2007년의 초기 플랫폼 공개와 상용 1.0 기기 발표를 구분합니다. Android 1.1은 2009년 2월 공개됐고 내부명은 Petit Four이며, PPT에 등장하는 iPhone은 Android 1.1의 코드명이 아닙니다.',links=[('Android 1.0 발표','https://android-developers.googleblog.com/2008/09/announcing-android-10-sdk-release-1.html'),('Android 1.1 발표','https://android-developers.googleblog.com/2009/02/android-11-sdk-release-1-now-available.html'),('AOSP 과거 버전 안내','https://android.googlesource.com/platform/docs/source.android.com/%2B/jb-dev/src/source/overview.md')])])
 ]
